229     template<typename genIUType>
230     GLM_FUNC_QUALIFIER genIUType mask(genIUType Bits)
231     {
232         GLM_STATIC_ASSERT(std::numeric_limits<genIUType>::is_integer, "'mask' accepts only integer values");
233 
234         return Bits >= sizeof(genIUType) * 8 ? ~static_cast<genIUType>(0) : (static_cast<genIUType>(1) << Bits) - static_cast<genIUType>(1);
235     }
