249     template<typename genIType>
250     GLM_FUNC_QUALIFIER genIType bitfieldRotateRight(genIType In, int Shift)
251     {
252         GLM_STATIC_ASSERT(std::numeric_limits<genIType>::is_integer, "'bitfieldRotateRight' accepts only integer values");
253 
254         int const BitSize = static_cast<genIType>(sizeof(genIType) * 8);
255         return (In << static_cast<genIType>(Shift)) | (In >> static_cast<genIType>(BitSize - Shift));
256     }
