309     GLM_FUNC_QUALIFIER int16 bitfieldInterleave(int8 x, int8 y)
310     {
311         union sign8
312         {
313             int8 i;
314             uint8 u;
315         } sign_x, sign_y;
316 
317         union sign16
318         {
319             int16 i;
320             uint16 u;
321         } result;
322 
323         sign_x.i = x;
324         sign_y.i = y;
325         result.u = bitfieldInterleave(sign_x.u, sign_y.u);
326 
327         return result.i;
328     }
