340     GLM_FUNC_QUALIFIER u8vec2 bitfieldDeinterleave(glm::uint16 x)
341     {
342         uint16 REG1(x);
343         uint16 REG2(x >>= 1);
344 
345         REG1 = REG1 & static_cast<uint16>(0x5555);
346         REG2 = REG2 & static_cast<uint16>(0x5555);
347 
348         REG1 = ((REG1 >> 1) | REG1) & static_cast<uint16>(0x3333);
349         REG2 = ((REG2 >> 1) | REG2) & static_cast<uint16>(0x3333);
350 
351         REG1 = ((REG1 >> 2) | REG1) & static_cast<uint16>(0x0F0F);
352         REG2 = ((REG2 >> 2) | REG2) & static_cast<uint16>(0x0F0F);
353 
354         REG1 = ((REG1 >> 4) | REG1) & static_cast<uint16>(0x00FF);
355         REG2 = ((REG2 >> 4) | REG2) & static_cast<uint16>(0x00FF);
356 
357         REG1 = ((REG1 >> 8) | REG1) & static_cast<uint16>(0xFFFF);
358         REG2 = ((REG2 >> 8) | REG2) & static_cast<uint16>(0xFFFF);
359 
360         return glm::u8vec2(REG1, REG2);
361     }
